        wheel_torque_nm[i] = 0.0;
    }
    *achieved_body_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    *saturation_mask = 0U;

    if ((!adcs_is_finite_vec3(&wheel_axes_body[0])) ||
        (!adcs_is_finite_vec3(&wheel_axes_body[1])) ||
        (!adcs_is_finite_vec3(&wheel_axes_body[2])) ||
        (!adcs_is_finite_vec3(desired_body_torque_nm))) {
        return ADCS_E_RANGE;
    }
    for (i = 0; i < 3; i++) {
        if ((!isfinite(wheel_torque_limit_nm[i])) || (wheel_torque_limit_nm[i] < 0.0)) {
            return ADCS_E_RANGE;
        }
    }

    for (i = 0; i < 3; i++) {
        n = adcs_vec3_norm(&wheel_axes_body[i]);
        if (fabs(n - 1.0) > tol) {
            return ADCS_E_RANGE;
        }
    }
    if (fabs(adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[1])) > tol ||
        fabs(adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[2])) > tol ||
        fabs(adcs_vec3_dot(&wheel_axes_body[1], &wheel_axes_body[2])) > tol) {
        return ADCS_E_RANGE;
    }

    *saturation_mask = 0U;
    for (i = 0; i < 3; i++) {
        double ui = -adcs_vec3_dot(&wheel_axes_body[i], desired_body_torque_nm);
        double lim = wheel_torque_limit_nm[i];
        double cl = ADCS_CLAMP(ui, -lim, lim);
        wheel_torque_nm[i] = cl;
        if (cl != ui) {
            *saturation_mask |= (uint32_t)(1U << i);
        }
    }

    for (i = 0; i < 3; i++) {
        adcs_vec3_t term = adcs_vec3_scale(&wheel_axes_body[i], wheel_torque_nm[i]);
        achieved = adcs_vec3_add(&achieved, &term);
    }
    *achieved_body_torque_nm = adcs_vec3_scale(&achieved, -1.0);

    return ADCS_OK;
}
